use std::borrow::Cow;
fn main() {
    let source = String::from("crab");
    let mut label: Cow<'_, str> = Cow::Borrowed(source.as_str());
    assert!(matches!(label, Cow::Borrowed(_)));
    label.to_mut().push('!');
    assert!(matches!(label, Cow::Owned(_)));
    assert_eq!(source, "crab");
    assert_eq!(label, "crab!");
}

