use std::borrow::Cow;
fn main() {
    let source = "crab";
    let mut text: Cow<'_, str> = Cow::Borrowed(source);
    text.to_mut().push('!');
    assert_eq!(source, "crab");
    assert_eq!(text, "crab!");
}
